def main():
    sheet = json.loads(SHEET.read_text())
    by_id = {r["id"]: r for r in CODED_NON_DEFAULT}
    labels = []
    for row in sorted(sheet, key=lambda x: x["id"]):
        rid = row["id"]
        if rid in by_id:
            labels.append(by_id[rid])
        else:
            p103 = row["posture_0103"]
            p = p103 if p103 in ("perched", "flying", "mixed") else "unknown"
            labels.append({
                "id": rid,
                "context": row["context"],
                "posture_0103": p103,
                "posture": p,
                "posture_preserve_0103": p,
                "pred_vocal_checklist": False,
            })

    out = {"total": len(labels), "labels": labels}
    (HERE / "checklist_posture_labels.json").write_text(json.dumps(out, indent=2))
    print("Total coded:", len(labels), "Counts:", dict(Counter((r["context"], r["posture"]) for r in labels)))

    # Print spot audit of newly recovered perched hawks and upgraded mixed hawks
    s_map = {r["id"]: r for r in sheet}
    for rid in [23402, 29119, 30296, 31427, 32497, 32545, 24663, 32207]:
        r = s_map[rid]
        c = by_id[rid]
        print(f"AUDIT {rid} ({c['context']} {c['posture_0103']}->{c['posture']}): cl='{r['checklist_comments'][:80]}' sib={r['sibling_obs']}")


if __name__ == "__main__":
    main()
